  "stuSess.refundContactNote": "Para solicitar um reembolso, entre em contacto com <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>.",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">Dúvidas ou problemas? Entre em contacto com <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>.</p><p class=\"font-semibold text-emerald-900\">O seu reembolso foi iniciado pela Stripe.</p><p class=\"text-emerald-800 mt-1\">Reembolsos no cartão costumam ser recebidos em cerca de <strong>5–10 dias úteis</strong> (o prazo pode variar conforme o banco). Se não receber o valor no prazo habitual, envie um email para <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>.</p>",
  "stuSess.refundSuccessManualTutor": "<p>Esta aula não parece ter sido paga pela Stripe da Tutlio (por exemplo, por transferência bancária ou em dinheiro). Não há reembolso automático neste caso.</p><p class=\"mt-2\">Para combinar o reembolso, entre em contacto com o seu explicador <strong>{tutor}</strong> — use o email ou os dados das suas reservas ou fornecidos pelo explicador.</p>",
  "stuSess.refundSuccessManualOrg": "<p>Esta aula não parece ter sido paga pela Stripe da Tutlio (por exemplo, por transferência bancária ou em dinheiro). Não há reembolso automático neste caso.</p><p class=\"mt-2\">Como as suas aulas são oferecidas por uma organização, entre em contacto com o <strong>administrador da organização</strong> (por meio do seu explicador ou dos contactos publicados pela organização).</p>",
  "stuSess.refundTutorFallback": "o seu explicador",
