  "orgTutorPolicy.title": "Regras internas para explicadores",
  "orgTutorPolicy.intro": "Leia as regras internas da organização antes de usar a plataforma.",
  "orgTutorPolicy.acceptBtn": "Entendi",
  "orgTutorPolicy.viewBtn": "Ver regras internas",
  "orgTutorPolicy.s1Title": "1. Disposições gerais",
  "orgTutorPolicy.s1Body": "Estas regras regulam a utilização da plataforma Tutlio (a \"Plataforma\") enquanto professor ou explicador (o \"Explicador\"). Foi convidado a utilizar a Plataforma pela empresa de serviços educativos, escola ou centro de explicações que representa (a \"Organização\"). A manutenção técnica e o apoio à Plataforma são assegurados pela MB Tutlio. Ao utilizar a sua conta, aceita estas Regras e a Política de Privacidade.",
  "orgTutorPolicy.s2Title": "2. Gestão da conta e agendas",
  "orgTutorPolicy.s2Intro": "A Plataforma foi desenvolvida para que não precise gastar tempo combinando horários de aulas com os alunos.",
  "orgTutorPolicy.s2Link": "Link exclusivo: recebe um link pessoal de agendamento de aulas (com base nas disciplinas que ensina), que os alunos usam para agendar aulas.",
  "orgTutorPolicy.s2Calendar": "Sincronização do calendário: a sua disponibilidade depende diretamente da integração com o Google Calendar (sincronização de 2 vias). É pessoalmente responsável por garantir que os horários livres exibidos no calendário estejam corretos e atualizados. A Plataforma não permitirá que os alunos agendem horários marcados como ocupados no seu calendário.",
  "orgTutorPolicy.s2Security": "Segurança da conta: a sua conta é pessoal. Deve manter as suas credenciais de acesso seguras e não partilhá-las com terceiros.",
  "orgTutorPolicy.s3Title": "3. Cancelamento de aulas e lista de espera",
  "orgTutorPolicy.s3Intro": "A Plataforma ajuda a aproveitar ao máximo a sua agenda e evitar horários vazios:",
  "orgTutorPolicy.s3Auto": "Se um aluno cancelar uma aula, a Plataforma enviará automaticamente uma notificação (SMS/email) a outros alunos da sua lista de espera, oferecendo o horário liberado. Nenhuma ação adicional será necessária da sua parte.",
  "orgTutorPolicy.s3Rules": "As regras de cancelamento de aulas (antecedência necessária para cancelar e consequências) são definidas pela sua Organização.",
  "orgTutorPolicy.s4Title": "4. Finanças e pagamentos",
  "orgTutorPolicy.s4Intro": "Não precisa de se preocupar com a emissão de faturas nem com a cobrança de pagamentos aos encarregados de educação:",
  "orgTutorPolicy.s4Advance": "Todos os pagamentos dos alunos (ou encarregados de educação) pelas suas aulas são cobrados antecipadamente pela Plataforma e transferidos diretamente para a sua Organização.",
  "orgTutorPolicy.s4Confirmed": "Ministra uma aula somente quando ela está confirmada no sistema (o que significa que já foi cobrada).",
  "orgTutorPolicy.s4Contact": "Para tratar da sua remuneração, calendário de transferências e outros assuntos financeiros, entre em contacto diretamente com o administrador da sua Organização. A MB Tutlio não realiza transações financeiras diretas com os Explicadores.",
  "orgTutorPolicy.s5Title": "5. Proteção de dados dos alunos (GDPR)",
  "orgTutorPolicy.s5Intro": "Como Explicador, tem acesso aos dados pessoais dos alunos, anotações internas e materiais de aprendizagem. Compromete-se a:",
  "orgTutorPolicy.s5Use": "Usar esses dados exclusivamente para organizar e ministrar aulas.",
  "orgTutorPolicy.s5NoCopy": "Não copiar, exportar ou distribuir informações de contacto de alunos ou encarregados de educação fora da Plataforma.",
  "orgTutorPolicy.s5Notes": "Proteger os registos internos da Organização (anotações sobre o progresso dos alunos), visíveis apenas para si e para a administração da Organização, e não para alunos ou encarregados de educação.",
  "orgTutorPolicy.s5Termination": "Ao encerrar o seu vínculo profissional com a Organização, o seu acesso a esses dados será revogado imediatamente.",
  "orgTutorPolicy.s6Title": "6. Funcionamento técnico e limitação de responsabilidade",
  "orgTutorPolicy.s6Body": "É proibido usar a Plataforma para fins ilícitos, distribuir links maliciosos nos materiais das aulas ou prejudicar o funcionamento do sistema de qualquer outra forma. A MB Tutlio garante o funcionamento e a manutenção técnica da Plataforma, mas não assume responsabilidade por interrupções causadas pela sua ligação à internet, falhas de dispositivos ou definições incorretas do Google Calendar.",
  "orgTutorPolicy.s7Title": "7. Suporte e contactos",
  "orgTutorPolicy.s7Org": "Para dúvidas sobre horários de aulas, remuneração, atribuição de alunos ou organização do trabalho, entre em contacto com o administrador da sua Organização.",
  "orgTutorPolicy.s7Tech": "Em caso de erros técnicos da Plataforma (falha na sincronização do calendário ou no recebimento de notificações), informe o administrador da sua Organização, que entrará em contacto com a equipa de suporte técnico da Tutlio.",
  "register.orgPolicyConsent": "Ao usar a nossa plataforma, concorda com as",
  "register.orgPolicyLink": "políticas internas",
