  "quiz.info.story.school.story": "“Queríamos um lugar onde a equipa pudesse acompanhar uma família desde a inscrição e o contrato até cada prestação. A Tutlio dá-nos essa continuidade sem precisarmos de manter folhas de cálculo paralelas.”",
