  "quiz.info.assurance.solo.eyebrow": "Feita para começar de forma prática",
  "quiz.info.assurance.solo.title": "Não precisa reorganizar todo o seu negócio no primeiro dia",
  "quiz.info.assurance.solo.body": "Um sistema útil deve aliviar a pressão rapidamente e crescer apenas quando precisar de mais.",
  "quiz.info.assurance.solo.point1": "Comece pelo calendário e pelos alunos e adicione finanças e automação no seu ritmo.",
  "quiz.info.assurance.solo.point2": "Mantenha as informações das aulas e dos alunos num espaço de trabalho feito para explicações.",
