  "quiz.info.assurance.company.eyebrow": "Controlo para uma equipa em crescimento",
  "quiz.info.assurance.company.title": "Partilhar a visão do negócio não precisa significar dar acesso a tudo",
  "quiz.info.assurance.company.body": "A Tutlio foi desenvolvida para que administradores e explicadores trabalhem na mesma operação, com acesso adequado a cada perfil.",
