  "quiz.info.assurance.company.point2": "Centralize os dados operacionais sem obrigar todos os perfis a seguir o mesmo processo.",
  "quiz.info.assurance.company.point3": "Adicione explicadores e alunos numa estrutura organizacional preparada para crescer.",
  "quiz.info.assurance.school.eyebrow": "Confiança para operações sensíveis",
  "quiz.info.assurance.school.title": "Os registos escolares precisam de clareza, controlo de acesso e um histórico fiável",
  "quiz.info.assurance.school.body": "O fluxo escolar da Tutlio é organizado em torno da relação administrativa real entre equipa, alunos, encarregados de educação, contratos e pagamentos.",
  "quiz.info.assurance.school.point1": "Mantenha os dados da organização em fluxos administrativos escolares com controlo por perfil.",
  "quiz.info.assurance.school.point2": "Acompanhe as etapas dos contratos e pagamentos sem depender da memória de quem lê os emails.",
  "quiz.info.assurance.school.point3": "Prepare exportações estruturadas para os responsáveis pela contabilidade.",
