  "quiz.offer.testimonial.solo.name3": "Ieva",
  "quiz.offer.testimonial.solo.role3": "Explicadora de química e biologia",
  "quiz.offer.testimonial.solo.copy3": "“Uma página pública e o agendamento num único link ajudam novos alunos a decidir mais rápido, e eu não preciso mais enviar as mesmas informações a cada pessoa.”",
  "quiz.offer.testimonial.solo.name4": "Lukas",
  "quiz.offer.testimonial.solo.role4": "Explicador de física",
  "quiz.offer.testimonial.solo.copy4": "“Consigo ver imediatamente as aulas, alterações e situações de pagamento no calendário. A administração diária ficou muito mais rápida e clara.”",
  "quiz.offer.testimonial.company.name1": "PRO KLASĖ",
  "quiz.offer.testimonial.company.role1": "Equipa de uma organização de explicações",
  "quiz.offer.testimonial.company.copy1": "“As alterações nas aulas, os comentários dos explicadores e as horas trabalhadas chegavam em mensagens separadas. Agora, a equipa administrativa consegue ver o quadro completo numa única agenda.”",
  "quiz.offer.testimonial.company.name2": "Centro independente de explicações",
  "quiz.offer.testimonial.company.role2": "Proprietário · 8 explicadores",
  "quiz.offer.testimonial.company.copy2": "“Eu passava as noites de sexta-feira a comparar o calendário com as mensagens dos explicadores antes de preparar a folha de pagamento. Com a Tutlio, a maior parte dessa conferência já está feita.”",
  "quiz.offer.testimonial.company.name3": "Estúdio de aulas de idiomas",
  "quiz.offer.testimonial.company.role3": "Responsável por operações · 14 explicadores",
  "quiz.offer.testimonial.company.copy3": "“Quando uma aula muda, a equipa vê a mesma atualização imediatamente. Temos menos mensagens de acompanhamento, e os encarregados de educação recebem respostas muito mais claras.”",
  "quiz.offer.testimonial.company.name4": "Centro de preparação para provas",
  "quiz.offer.testimonial.company.role4": "Coordenador financeiro · 22 explicadores",
  "quiz.offer.testimonial.company.copy4": "“As nossas regras de remuneração variam consoante o tipo de aula, pelo que o fecho do mês exigia muitas verificações manuais. O fluxo da Tutlio tornou esse processo muito mais tranquilo.”",
  "quiz.offer.testimonial.school.name1": "VšĮ “Laisvi vaikai”",
  "quiz.offer.testimonial.school.role1": "Equipa de administração escolar",
  "quiz.offer.testimonial.school.copy1": "“A melhoria mais clara é ver a situação do contrato, da assinatura e do pagamento sem precisar perguntar a várias pessoas ou conferir ficheiros separados.”",
  "quiz.offer.testimonial.school.name2": "Escola comunitária independente",
  "quiz.offer.testimonial.school.role2": "Coordenador de inscrições · 86 alunos",
  "quiz.offer.testimonial.school.copy2": "“A época de inscrições significava acompanhar formulários, dados dos encarregados de educação e contratos assinados em pastas separadas. Agora, a nossa equipa consegue acompanhar cada família num único lugar.”",
  "quiz.offer.testimonial.school.name3": "Centro de aprendizagem extracurricular",
  "quiz.offer.testimonial.school.role3": "Administrador · 120 alunos",
  "quiz.offer.testimonial.school.copy3": "“Os planos de prestações tornaram o acompanhamento dos pagamentos muito mais tranquilo. Consigo ver o que está a vencer antes de falar com um encarregado de educação, em vez de refazer a lista à mão.”",
  "quiz.offer.testimonial.school.name4": "Escola de educação artística",
  "quiz.offer.testimonial.school.role4": "Coordenador financeiro · 9 programas",
  "quiz.offer.testimonial.school.copy4": "“A exportação para a contabilidade agora parte dos mesmos registos que usamos para contratos e pagamentos, pelo que o fecho do mês exige muito menos correções.”",
