  "schoolsLanding.ctaBannerTitle": "Pronto para digitalizar a sua escola?",
  "schoolsLanding.ctaBannerDesc": "Contacte a nossa equipa para saber como a Tutlio Schools pode simplificar a administração, melhorar a eficiência e apoiar o crescimento.",
  "schoolsLanding.ctaBannerBtn": "Contacte-nos",
  "schoolsLanding.faq.whatIsQ": "O que é a Tutlio para escolas?",
  "schoolsLanding.faq.whatIsA": "A Tutlio Schools é um software de gestão para escolas de explicações: horários dos professores, CRM de alunos, contratos, pagamentos e relatórios numa só plataforma.",
  "schoolsLanding.faq.whoForQ": "A quem se destina a Tutlio Schools?",
  "schoolsLanding.faq.whoForA": "Escolas de línguas, centros de explicações, escolas de música, programas de preparação para exames e qualquer organização que faça a gestão de vários explicadores e alunos.",
  "schoolsLanding.faq.contractsQ": "Podemos gerir contratos e pagamentos?",
  "schoolsLanding.faq.contractsA": "Sim. A plataforma suporta modelos de contrato, assinatura eletrónica, pagamentos a prestações, pagamentos Stripe e relatórios financeiros.",
  "schoolsLanding.faq.pricingQ": "Como funcionam os preços para escolas?",
  "schoolsLanding.faq.pricingA": "As escolas recebem preços à medida, consoante o número de explicadores e as necessidades. Contacte-nos para uma proposta personalizada.",
  "schoolsLanding.faq.trialQ": "Podemos experimentar antes de comprar?",
  "schoolsLanding.faq.trialA": "Sim - marque uma consultoria e demonstração gratuitas. Mostramos-lhe como a Tutlio se ajusta ao dia a dia da sua escola.",
