  "nav.compare": "Comparação",
  "landing.custom.badge": "A grande diferença",
  "landing.custom.title": "Software que se adapta à sua forma de trabalhar - e não ao contrário",
  "landing.custom.sub": "Cada escola e cada agência funciona de forma um pouco diferente. Quando o fluxo padrão não serve, adaptamos a Tutlio ao seu processo - normalmente em semanas, não em trimestres. Alguns exemplos que já construímos para clientes:",
  "landing.custom.ex1Title": "Contratos anuais com assinatura eletrónica",
  "landing.custom.ex1Desc": "Uma escola privada precisava que os encarregados de educação assinassem os contratos anuais online, pagassem a prestações e que cada pagamento aparecesse numa exportação pronta para a contabilidade. Hoje todo o ciclo decorre dentro da Tutlio.",
  "landing.custom.ex2Title": "Regras de pagamento e comissão dos explicadores",
  "landing.custom.ex2Desc": "Uma agência paga a cada explicador consoante a disciplina e o tipo de aula, acrescentando uma comissão da empresa. Modelámos as regras deles, por isso os extratos mensais dos explicadores e as faturas são gerados automaticamente.",
  "landing.custom.ex3Title": "Ofertas para encarregados de educação com um clique",
  "landing.custom.ex3Desc": "Uma escola queria propor aulas extra por email e permitir que os encarregados de educação as aceitassem com um único clique - sem conta e sem impressões. A aceitação, a faturação e o convite para a primeira aula acontecem agora sozinhos.",
  "landing.custom.ex4Title": "A sua marca, no seu site",
  "landing.custom.ex4Desc": "Uma organização queria o seu próprio logótipo e as suas cores, além de um início de sessão integrado no site, para que alunos e encarregados de educação nunca sentissem que o tinham deixado. Hoje a Tutlio funciona sob a marca deles.",
  "landing.custom.note": "Nada disto é uma edição especial. Cada adaptação passa a fazer parte do mesmo produto que a sua equipa já usa, com todas as atualizações futuras incluídas.",
  "landing.custom.cta": "Conte-nos como trabalha",
  "landing.custom.soloTitle": "Falta alguma coisa?",
  "landing.custom.soloNote": "Criamos regularmente funcionalidades para clientes específicos - desde uma regra de pagamento até um fluxo de trabalho completo. Diga-nos o que lhe pouparia tempo.",
  "compStu.debtNo": "Não",
  "stats.cancellationPartTutor": "explicador: {count}",
  "compare.hub.badge": "Comparação",
  "compare.hub.title": "Tutlio em comparação com outros programas de gestão de explicações",
  "compare.hub.subtitle": "Comparações honestas, ponto a ponto, com as ferramentas que explicadores e centros de estudos consideram com mais frequência. Quando um concorrente é mais adequado, dizemo-lo.",
